---
package external

import (
	"context"
	"errors"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

// Wrap returns the Agent wrapped as an agent.Agent that implements ALL optional
// interfaces (forwarding to the underlying external agent) plus CapabilityDeclarer.
// The As* helpers in the agent package use DeclaredCapabilities() to gate access,
// so callers only see capabilities the external binary actually declared.
func Wrap(ea *Agent) (agent.Agent, error) {
	if ea == nil {
		return nil, errors.New("unable to wrap nil agent")
	}
	base := &wrappedAgent{
		ea:   ea,
		caps: ea.info.Capabilities,
	}
	if len(ea.info.ProtectedFiles) > 0 {
		return &wrappedAgentWithProtectedFiles{wrappedAgent: base}, nil
	}
	return base, nil
}

// wrappedAgent forwards all agent.Agent and optional interface methods to the
// underlying external Agent. Capability gating is handled by DeclaredCapabilities()
// and the As* helpers in the agent package.
type wrappedAgent struct {
	ea   *Agent
	caps agent.DeclaredCaps
}

// wrappedAgentWithProtectedFiles opt-ins external agents to ProtectedFilesProvider
// only when the binary actually advertised protected_files in its info response.
type wrappedAgentWithProtectedFiles struct {
	*wrappedAgent
}

// --- CapabilityDeclarer ---

func (w *wrappedAgent) DeclaredCapabilities() agent.DeclaredCaps { return w.caps }

// --- agent.Agent ---

func (w *wrappedAgent) Name() types.AgentName { return w.ea.Name() }
func (w *wrappedAgent) Type() types.AgentType { return w.ea.Type() }
func (w *wrappedAgent) Description() string   { return w.ea.Description() }
func (w *wrappedAgent) IsPreview() bool       { return w.ea.IsPreview() }
func (w *wrappedAgent) DetectPresence(ctx context.Context) (bool, error) {
	return w.ea.DetectPresence(ctx)
}
func (w *wrappedAgent) ProtectedDirs() []string                   { return w.ea.ProtectedDirs() }
func (w *wrappedAgent) ReadTranscript(ref string) ([]byte, error) { return w.ea.ReadTranscript(ref) }
func (w *wrappedAgent) ChunkTranscript(ctx context.Context, c []byte, m int) ([][]byte, error) {
	return w.ea.ChunkTranscript(ctx, c, m)
}
func (w *wrappedAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return w.ea.ReassembleTranscript(chunks)
}
func (w *wrappedAgent) GetSessionID(input *agent.HookInput) string { return w.ea.GetSessionID(input) }
func (w *wrappedAgent) GetSessionDir(repoPath string) (string, error) {
	return w.ea.GetSessionDir(repoPath)
}
func (w *wrappedAgent) ResolveSessionFile(dir, id string) string {
	return w.ea.ResolveSessionFile(dir, id)
}
func (w *wrappedAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	return w.ea.ReadSession(input)
}
func (w *wrappedAgent) WriteSession(ctx context.Context, s *agent.AgentSession) error {
	return w.ea.WriteSession(ctx, s)
}
func (w *wrappedAgent) FormatResumeCommand(id string) string { return w.ea.FormatResumeCommand(id) }

// --- HookSupport ---

func (w *wrappedAgent) HookNames() []string { return w.ea.HookNames() }
func (w *wrappedAgent) ParseHookEvent(ctx context.Context, name string, stdin io.Reader) (*agent.Event, error) {
	return w.ea.ParseHookEvent(ctx, name, stdin)
}
func (w *wrappedAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
	return w.ea.InstallHooks(ctx, localDev, force)
}
func (w *wrappedAgent) UninstallHooks(ctx context.Context) error { return w.ea.UninstallHooks(ctx) }
func (w *wrappedAgent) AreHooksInstalled(ctx context.Context) bool {
	return w.ea.AreHooksInstalled(ctx)
}

// --- TranscriptAnalyzer ---

func (w *wrappedAgent) GetTranscriptPosition(path string) (int, error) {
	return w.ea.GetTranscriptPosition(path)
}
func (w *wrappedAgent) ExtractModifiedFilesFromOffset(path string, offset int) ([]string, int, error) {
	return w.ea.ExtractModifiedFilesFromOffset(path, offset)
}
func (w *wrappedAgent) ExtractPrompts(ref string, offset int) ([]string, error) {
	return w.ea.ExtractPrompts(ref, offset)
}
func (w *wrappedAgent) ExtractSummary(ref string) (string, error) {
	return w.ea.ExtractSummary(ref)
}

// --- TranscriptPreparer ---

func (w *wrappedAgent) PrepareTranscript(ctx context.Context, ref string) error {
	return w.ea.PrepareTranscript(ctx, ref)
}

// --- TokenCalculator ---

func (w *wrappedAgent) CalculateTokenUsage(data []byte, offset int) (*agent.TokenUsage, error) {
	return w.ea.CalculateTokenUsage(data, offset)
}

// --- TextGenerator ---

func (w *wrappedAgent) GenerateText(ctx context.Context, prompt string, model string) (string, error) {
	return w.ea.GenerateText(ctx, prompt, model)
}

// --- TranscriptCompactor ---

func (w *wrappedAgent) CompactTranscript(ctx context.Context, sessionRef string) (*agent.CompactedTranscript, error) {
	return w.ea.CompactTranscript(ctx, sessionRef)
}

// --- HookResponseWriter ---

func (w *wrappedAgent) WriteHookResponse(message string) error {
	return w.ea.WriteHookResponse(message)
}

func (w *wrappedAgentWithProtectedFiles) ProtectedFiles() []string {
	return w.ea.ProtectedFiles()
}

// --- SubagentAwareExtractor ---

func (w *wrappedAgent) ExtractAllModifiedFiles(data []byte, offset int, dir string) ([]string, error) {
	return w.ea.ExtractAllModifiedFiles(data, offset, dir)
}
func (w *wrappedAgent) CalculateTotalTokenUsage(data []byte, offset int, dir string) (*agent.TokenUsage, error) {
	return w.ea.CalculateTotalTokenUsage(data, offset, dir)
}

// IsExternal reports whether ag is backed by an external agent binary.
func IsExternal(ag agent.Agent) bool {
	switch ag.(type) {
	case *wrappedAgent, *wrappedAgentWithProtectedFiles:
		return true
	default:
		return false
	}
}

var (
	_ agent.CapabilityDeclarer     = (*wrappedAgent)(nil)
	_ agent.HookSupport            = (*wrappedAgent)(nil)
	_ agent.TranscriptAnalyzer     = (*wrappedAgent)(nil)
	_ agent.TranscriptPreparer     = (*wrappedAgent)(nil)
	_ agent.TokenCalculator        = (*wrappedAgent)(nil)
	_ agent.TextGenerator          = (*wrappedAgent)(nil)
	_ agent.TranscriptCompactor    = (*wrappedAgent)(nil)
	_ agent.HookResponseWriter     = (*wrappedAgent)(nil)
	_ agent.SubagentAwareExtractor = (*wrappedAgent)(nil)
)
package external

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const (
	binaryPrefix = "entire-agent-"
	osWindows    = "windows"
)

// discoveryTimeout caps the total time spent scanning $PATH for external agents.
const discoveryTimeout = 10 * time.Second

var (
	statExternalAgent     = os.Stat       //nolint:gochecknoglobals // narrow test seam for stat failures
	lookPathExternalAgent = exec.LookPath //nolint:gochecknoglobals // narrow test seam for lookup failures
)

// DiscoverAndRegister scans $PATH for executables matching "entire-agent-<name>",
// calls their "info" subcommand, and registers them in the agent registry.
// Binaries whose name conflicts with an already-registered agent are skipped.
// Errors during discovery are logged but do not prevent other agents from loading.
// Discovery is skipped when the external_agents setting is not enabled.
func DiscoverAndRegister(ctx context.Context) {
	if !settings.IsExternalAgentsEnabled(ctx) {
		logging.Debug(ctx, "external agent discovery disabled (external_agents not enabled in settings)")
		return
	}
	discoverAndRegister(ctx)
}

// DiscoverAndRegisterAlways is like DiscoverAndRegister but bypasses the
// external_agents settings check. Use this in interactive setup flows where
// the user explicitly chooses agents.
func DiscoverAndRegisterAlways(ctx context.Context) {
	discoverAndRegister(ctx)
}

// DiscoverAndRegisterNamedAlways discovers and registers only the external
// agent binary matching name. It bypasses the external_agents setting for
// explicit, one-invocation selections without executing unrelated plugins.
func DiscoverAndRegisterNamedAlways(ctx context.Context, name types.AgentName) error {
	return discoverAndRegisterNamed(ctx, name, discoveryTimeout)
}

// discoveryCanceled reports whether either the caller's context or the derived
// discovery-timeout context has been cancelled.
//
// Both must be consulted. A context closes its own Done channel *before* cancelling
// its children, so a goroutine that has just observed the caller's cancellation can
// run while the derived context still reports no error — and when the caller is not a
// standard context, propagation happens in a watcher goroutine, widening the window
// further. Checking only the derived context therefore lets a caller whose deadline
// expired mid-operation look like it is still live.
func discoveryCanceled(caller, derived context.Context) bool {
	return caller.Err() != nil || derived.Err() != nil
}

// discoveryCtxErr wraps whichever of the two contexts has been cancelled, preferring
// the caller's, and returns nil when neither has. op names the stage for the message.
// See discoveryCanceled for why the caller's context must be consulted too: missing it
// lets a caller whose deadline expired mid-lookup receive a nil error and a silently
// skipped agent instead of its context error.
func discoveryCtxErr(caller, derived context.Context, op string) error {
	err := caller.Err()
	if err == nil {
		err = derived.Err()
	}
	if err == nil {
		return nil
	}
	return fmt.Errorf("%s: %w", op, err)
}

func discoverAndRegisterNamed(ctx context.Context, name types.AgentName, timeout time.Duration) error {
	if name == "" {
		return nil
	}
	if strings.ContainsAny(string(name), `/\`) {
		return fmt.Errorf("invalid external agent name %q: contains path separators", name)
	}
	if _, err := agent.Get(name); err == nil {
		return nil
	}

	// `ctx` deliberately stays the CALLER's context; the derived timeout gets its own
	// name. Shadowing `ctx` with the derived context is what caused the bug this
	// function is guarding against, and it left the trap in place for the next edit.
	discoveryCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	if err := discoveryCtxErr(ctx, discoveryCtx, fmt.Sprintf("discovering external agent %q", name)); err != nil {
		return err
	}

	binName := binaryPrefix + string(name)
	binPath, err := lookPathExternalAgent(binName)
	if ctxErr := discoveryCtxErr(ctx, discoveryCtx, fmt.Sprintf("looking up external agent %q binary %q", name, binName)); ctxErr != nil {
		return ctxErr
	}
	if err != nil {
		if errors.Is(err, exec.ErrNotFound) {
			return nil
		}
		return fmt.Errorf("looking up external agent %q binary %q: %w", name, binName, err)
	}
	registered, err := registerExternalAgent(discoveryCtx, binPath, name)
	if err != nil {
		return err
	}
	if !registered {
		return fmt.Errorf("external agent %q binary %q was found but could not be registered", name, binPath)
	}
	return nil
}

// discoverAndRegister contains the shared scanning logic for external agent discovery.
func discoverAndRegister(ctx context.Context) {
	// As above: `ctx` remains the caller's, the derived timeout is named.
	discoveryCtx, cancel := context.WithTimeout(ctx, discoveryTimeout)
	defer cancel()

	pathEnv := os.Getenv("PATH")
	if pathEnv == "" {
		return
	}

	// Collect already-registered names to avoid conflicts.
	registered := make(map[types.AgentName]bool)
	for _, name := range agent.List() {
		registered[name] = true
	}

	seen := make(map[string]bool) // deduplicate binaries across PATH dirs
	for _, dir := range filepath.SplitList(pathEnv) {
		if discoveryCanceled(ctx, discoveryCtx) {
			logging.Debug(ctx, "external agent discovery timed out")
			return
		}

		matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
		if err != nil {
			continue // skip unreadable directories
		}
		for _, binPath := range matches {
			if discoveryCanceled(ctx, discoveryCtx) {
				logging.Debug(ctx, "external agent discovery timed out")
				return
			}

			name := filepath.Base(binPath)
			if seen[name] {
				continue
			}
			seen[name] = true

			// Strip Windows executable extensions (.exe, .bat) before deriving agent name.
			// On Unix, binaries have no extension, so this is a no-op.
			cleanName := StripExeExt(name)
			agentName := types.AgentName(strings.TrimPrefix(cleanName, binaryPrefix))
			if registered[agentName] {
				logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
					slog.String("binary", name),
					slog.String("agent", string(agentName)))
				continue
			}

			registeredAgent, err := registerExternalAgent(discoveryCtx, binPath, agentName)
			if err != nil {
